#!/usr/bin/env node
// Grade a learner's primitive classification against docs/foundations/classification-answer-key.md.
// Zero dependencies, Node 22.
//
// Usage: node docs/foundations/grade-classification.mjs <answers.json> [--key <answer-key.md>] [--pass <n>]
// answers.json: { "N01": { "answer": "hook", "why": "..." }, ... }  (a bare string "hook" is also accepted)
// Exit codes: 0 score >= pass mark (default 8), 1 below pass mark, 2 usage or I/O error.
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export const PRIMITIVES = ["prompt", "skill", "agent", "workflow", "mcp", "hook"];
const DEFAULT_KEY = join(dirname(fileURLToPath(import.meta.url)), "classification-answer-key.md");

// Split a markdown table row on pipes that are not escaped as \|
function cells(row) {
  return row.trim().replace(/^\|/, "").replace(/\|$/, "").split(/(?<!\\)\|/).map((c) => c.trim().replace(/\\\|/g, "|"));
}

export function parseKey(markdown) {
  const key = new Map();
  for (const line of markdown.split("\n")) {
    if (!/^\| N\d{2} \|/.test(line)) continue;
    const [id, need, answer, accepted, justification] = cells(line);
    if (!PRIMITIVES.includes(answer)) throw new Error(`${id}: answer "${answer}" is not a primitive`);
    const alt = accepted === "none" ? [] : accepted.split(/,\s*/);
    key.set(id, { need, answer, accepted: alt, justification });
  }
  return key;
}

export function grade(key, answers) {
  const rows = [];
  let score = 0;
  for (const [id, k] of key) {
    const raw = answers[id];
    const given = String((raw && typeof raw === "object" ? raw.answer : raw) || "").trim().toLowerCase();
    const why = raw && typeof raw === "object" ? String(raw.why || "").trim() : "";
    let verdict;
    if (!given) verdict = "MISSING";
    else if (!PRIMITIVES.includes(given)) verdict = "INVALID";
    else if (given === k.answer) verdict = "CORRECT";
    else if (k.accepted.includes(given)) verdict = "ACCEPTED";
    else verdict = "WRONG";
    const points = verdict === "CORRECT" || verdict === "ACCEPTED" ? 1 : 0;
    score += points;
    rows.push({ id, given: given || "-", expected: k.answer, verdict, points, noWhy: points === 1 && why.length < 20 });
  }
  return { score, total: key.size, rows };
}

function main(argv) {
  const args = [...argv];
  const opt = (name, def) => { const i = args.indexOf(name); if (i < 0) return def; const v = args[i + 1]; args.splice(i, 2); return v; };
  const keyPath = opt("--key", DEFAULT_KEY);
  const pass = Number(opt("--pass", "8"));
  const [answersPath] = args;
  if (!answersPath) { process.stderr.write("usage: grade-classification.mjs <answers.json> [--key <md>] [--pass <n>]\n"); return 2; }
  let key, answers;
  try {
    key = parseKey(readFileSync(keyPath, "utf8"));
    answers = JSON.parse(readFileSync(answersPath, "utf8"));
  } catch (e) { process.stderr.write(`ERROR ${e.message}\n`); return 2; }
  const r = grade(key, answers);
  for (const row of r.rows) {
    let line = `${row.id}  ${row.verdict.padEnd(8)} given=${row.given.padEnd(8)} key=${row.expected}`;
    if (row.verdict === "WRONG") line += `  -> ${key.get(row.id).justification}`;
    if (row.verdict === "ACCEPTED") line += "  (alternative answer: check the justification names the agent it runs in)";
    if (row.noWhy) line += "  (warning: justification missing or under 20 characters)";
    process.stdout.write(line + "\n");
  }
  const ok = r.score >= pass;
  process.stdout.write(`SCORE ${r.score}/${r.total} (pass mark ${pass}) ${ok ? "PASS" : "FAIL"}\n`);
  return ok ? 0 : 1;
}

if (import.meta.url === `file://${process.argv[1]}`) process.exit(main(process.argv.slice(2)));

#!/usr/bin/env node
// Validate an Agent Contract markdown file (course convention; see agents/CONTRACT_TEMPLATE.md).
// Zero dependencies, Node 22.
//
// Usage:
//   node docs/foundations/validate-contract.mjs <contract.md> [more.md ...]   validate filled contracts
//   node docs/foundations/validate-contract.mjs --template agents/CONTRACT_TEMPLATE.md   headings only
//   node docs/foundations/validate-contract.mjs --json <contract.md>   print the agentContracts JSON object
// Exit codes: 0 valid, 1 invalid, 2 usage or I/O error.
import { readFileSync } from "node:fs";

export const FIELDS = [
  "purpose", "inputs", "outputs", "tools", "permissions", "must", "mustNot",
  "failureConditions", "validation", "handoffFormat", "humanGate",
];
export const LIST_FIELDS = new Set(["inputs", "outputs", "tools", "must", "mustNot", "failureConditions"]);
export const ROSTER = ["architect", "developer", "reviewer", "tester", "security", "sre", "orchestrator"];
// Built-in tool names as Claude Code spells them (build/CLAUDE_CODE_FACTS.md section 1), plus MCP tools.
const TOOLS = new Set([
  "Read", "Grep", "Glob", "LSP", "Bash", "PowerShell", "Edit", "Write", "NotebookEdit", "WebFetch",
  "WebSearch", "TodoWrite", "Skill", "ToolSearch", "EnterWorktree", "ExitWorktree", "Monitor",
  "TaskStop", "SendMessage", "Agent",
]);
const MCP_TOOL = /^mcp__[A-Za-z0-9_-]+(__[A-Za-z0-9_*-]+)?$/;
const ENFORCEMENT = /\[(mechanism|convention):\s*[^\]]+\]\s*$/;
const GATE_MECHANISM = /plan mode|permissionMode: plan|`ask`|\bask rule|pull[- ]request approval|PR approval|hook|exit 2/i;

const stripComments = (s) => s.replace(/<!--[\s\S]*?-->/g, "");
const stripCode = (s) => s.replace(/`[^`\n]*`/g, "``");

export function parseContract(markdown) {
  const text = stripComments(markdown);
  const title = (text.match(/^# Agent Contract:\s*(.+?)\s*$/m) || [])[1] || null;
  const sections = [];
  let current = null;
  for (const line of text.split("\n")) {
    const h = line.match(/^## (\S.*?)\s*$/);
    if (h) { current = { name: h[1], lines: [] }; sections.push(current); continue; }
    if (/^# /.test(line)) { current = null; continue; }
    if (current) current.lines.push(line);
  }
  return { title, sections };
}

export function validateContract(markdown, { template = false } = {}) {
  const errors = [];
  const warnings = [];
  const { title, sections } = parseContract(markdown);
  const names = sections.map((s) => s.name);

  if (!title) errors.push('missing title line "# Agent Contract: <agent>"');
  else if (!template && !ROSTER.includes(title)) errors.push(`agent "${title}" is not in the roster (${ROSTER.join(", ")})`);

  for (const f of FIELDS) {
    const n = names.filter((x) => x === f).length;
    if (n === 0) errors.push(`missing section "## ${f}"`);
    if (n > 1) errors.push(`section "## ${f}" appears ${n} times`);
  }
  const known = names.filter((x) => FIELDS.includes(x));
  const expectedOrder = FIELDS.filter((f) => known.includes(f));
  if (known.join() !== expectedOrder.join()) errors.push(`sections out of order: expected ${expectedOrder.join(", ")}`);
  for (const x of names) if (!FIELDS.includes(x)) warnings.push(`extra section "## ${x}" is not an agentContracts field`);

  if (template) return { ok: errors.length === 0, errors, warnings };

  for (const s of sections) {
    if (!FIELDS.includes(s.name)) continue;
    const body = s.lines.join("\n").trim();
    const bullets = s.lines.filter((l) => /^- \S/.test(l)).map((l) => l.slice(2).trim());
    if (!body) { errors.push(`${s.name}: section is empty`); continue; }
    if (/<[a-z][^>\n]*>/i.test(stripCode(body))) errors.push(`${s.name}: unreplaced <placeholder> text`);
    if (LIST_FIELDS.has(s.name) && bullets.length === 0) errors.push(`${s.name}: needs at least one "- " bullet`);
    if (!LIST_FIELDS.has(s.name) && bullets.length > 0) errors.push(`${s.name}: must be a paragraph, not a bullet list`);
    if (s.name === "must" || s.name === "mustNot") {
      bullets.forEach((b, i) => {
        if (!ENFORCEMENT.test(b)) errors.push(`${s.name}[${i + 1}]: must end with [mechanism: ...] or [convention: ...]`);
      });
      const mech = bullets.filter((b) => /\[mechanism:/.test(b)).length;
      if (s.name === "mustNot" && bullets.length && mech === 0) warnings.push("mustNot: no rule is enforced by a mechanism; all are conventions");
    }
    if (s.name === "tools") {
      bullets.forEach((b) => {
        const name = b.split(/[\s(]/)[0];
        if (!TOOLS.has(name) && !MCP_TOOL.test(name)) errors.push(`tools: "${name}" is not a Claude Code tool name`);
      });
    }
    if (s.name === "humanGate" && !GATE_MECHANISM.test(body)) {
      errors.push("humanGate: name the real mechanism (plan mode, a permission ask rule, PR approval, or a hook that exits 2)");
    }
    if (s.name === "handoffFormat" && !body.includes(".ai-sdlc/runs/")) {
      errors.push("handoffFormat: must name the run-folder path .ai-sdlc/runs/<run-id>/NN-<agent>.md");
    }
  }
  return { ok: errors.length === 0, errors, warnings };
}

export function toAgentContract(markdown) {
  const { title, sections } = parseContract(markdown);
  const out = { agent: title };
  for (const f of FIELDS) {
    const s = sections.find((x) => x.name === f);
    const lines = s ? s.lines : [];
    out[f] = LIST_FIELDS.has(f)
      ? lines.filter((l) => /^- \S/.test(l)).map((l) => l.slice(2).trim())
      : lines.join("\n").trim().replace(/\s*\n\s*/g, " ");
  }
  return out;
}

function main(argv) {
  const template = argv.includes("--template");
  const json = argv.includes("--json");
  const files = argv.filter((a) => !a.startsWith("--"));
  if (files.length === 0) {
    process.stderr.write("usage: validate-contract.mjs [--template] [--json] <contract.md> [...]\n");
    return 2;
  }
  let failed = false;
  for (const file of files) {
    let md;
    try { md = readFileSync(file, "utf8"); } catch (e) { process.stderr.write(`ERROR ${file}: ${e.message}\n`); return 2; }
    const r = validateContract(md, { template });
    for (const w of r.warnings) process.stderr.write(`WARN  ${file}: ${w}\n`);
    for (const e of r.errors) process.stderr.write(`FAIL  ${file}: ${e}\n`);
    if (!r.ok) { failed = true; continue; }
    if (json) process.stdout.write(JSON.stringify(toAgentContract(md), null, 2) + "\n");
    else process.stdout.write(`OK    ${file}: ${FIELDS.length}/${FIELDS.length} contract sections${template ? " (template mode)" : ""}\n`);
  }
  return failed ? 1 : 0;
}

if (import.meta.url === `file://${process.argv[1]}`) process.exit(main(process.argv.slice(2)));

// Tests for the module 01-foundations scripts. Run from AI-SDLC/:
//   node --test docs/foundations/foundations.test.mjs
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { validateContract, toAgentContract, FIELDS } from "./validate-contract.mjs";
import { parseKey, grade, PRIMITIVES } from "./grade-classification.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..", "..");
const draft = readFileSync(join(HERE, "reviewer-contract-draft.md"), "utf8");
const template = readFileSync(join(ROOT, "agents", "CONTRACT_TEMPLATE.md"), "utf8");
const keyMd = readFileSync(join(HERE, "classification-answer-key.md"), "utf8");
const run = (script, args) => spawnSync(process.execPath, [join(HERE, script), ...args], { encoding: "utf8" });

test("reviewer draft is a valid contract", () => {
  const r = validateContract(draft);
  assert.deepEqual(r.errors, []);
  assert.equal(r.ok, true);
});

test("template passes template mode but fails as a filled contract", () => {
  assert.equal(validateContract(template, { template: true }).ok, true);
  const r = validateContract(template);
  assert.equal(r.ok, false);
  assert.ok(r.errors.some((e) => e.includes("unreplaced <placeholder>")));
});

test("missing section is reported", () => {
  const r = validateContract(draft.replace("## humanGate", "## Human gate"));
  assert.ok(r.errors.includes('missing section "## humanGate"'));
  assert.ok(r.warnings.some((w) => w.includes('"## Human gate"')));
});

test("sections out of order are reported", () => {
  const swapped = draft.replace("## must\n", "## TMP\n").replace("## mustNot\n", "## must\n").replace("## TMP\n", "## mustNot\n");
  assert.ok(validateContract(swapped).errors.some((e) => e.startsWith("sections out of order")));
});

test("must rule without enforcement tag fails", () => {
  const bad = draft.replace("[convention: human reviewer reads the handoff]", "");
  assert.ok(validateContract(bad).errors.some((e) => /^must\[3\]/.test(e)));
});

test("invented tool name fails", () => {
  const bad = draft.replace("- Glob\n", "- CodeSearch\n");
  assert.ok(validateContract(bad).errors.includes('tools: "CodeSearch" is not a Claude Code tool name'));
});

test("MCP tool names are accepted", () => {
  const ok = draft.replace("- Glob\n", "- Glob\n- mcp__fhir-lite__search_observations\n");
  assert.equal(validateContract(ok).ok, true);
});

test("humanGate without a real mechanism fails", () => {
  const i = draft.indexOf("## humanGate");
  const bad = draft.slice(0, i) + "## humanGate\n\nA senior engineer looks at the output when they have time.\n";
  assert.ok(validateContract(bad).errors.some((e) => e.startsWith("humanGate:")));
});

test("agent outside the roster fails", () => {
  const bad = draft.replace("# Agent Contract: reviewer", "# Agent Contract: code-reviewer");
  assert.ok(validateContract(bad).errors.some((e) => e.includes("not in the roster")));
});

test("toAgentContract yields every schema field with the right types", () => {
  const c = toAgentContract(draft);
  assert.deepEqual(Object.keys(c), ["agent", ...FIELDS]);
  assert.equal(c.agent, "reviewer");
  for (const f of ["inputs", "outputs", "tools", "must", "mustNot", "failureConditions"]) assert.ok(Array.isArray(c[f]) && c[f].length > 0, f);
  for (const f of ["purpose", "permissions", "validation", "handoffFormat", "humanGate"]) assert.equal(typeof c[f], "string");
  assert.deepEqual(c.tools, ["Read", "Grep", "Glob", "Bash (only `git diff`, `git log`, `git status`)"]);
});

test("validator CLI exit codes: 0 valid, 1 invalid, 2 usage", () => {
  assert.equal(run("validate-contract.mjs", [join(HERE, "reviewer-contract-draft.md")]).status, 0);
  assert.equal(run("validate-contract.mjs", [join(ROOT, "agents", "CONTRACT_TEMPLATE.md")]).status, 1);
  assert.equal(run("validate-contract.mjs", []).status, 2);
});

test("answer key parses ten needs with valid primitives", () => {
  const key = parseKey(keyMd);
  assert.equal(key.size, 10);
  for (const k of key.values()) {
    assert.ok(PRIMITIVES.includes(k.answer));
    for (const a of k.accepted) assert.ok(PRIMITIVES.includes(a));
  }
  assert.equal(key.get("N01").answer, "hook");
  assert.deepEqual(key.get("N09").accepted, ["skill"]);
});

test("grader scores correct, accepted, wrong and missing answers", () => {
  const key = parseKey(keyMd);
  const r = grade(key, { N01: "hook", N04: { answer: "skill", why: "reuse" }, N09: { answer: "skill", why: "production-rca inside the sre agent" } });
  const by = Object.fromEntries(r.rows.map((x) => [x.id, x.verdict]));
  assert.equal(by.N01, "CORRECT");
  assert.equal(by.N04, "WRONG");
  assert.equal(by.N09, "ACCEPTED");
  assert.equal(by.N02, "MISSING");
  assert.equal(r.score, 2);
});

test("grader CLI passes the example answers at 8/10", () => {
  const r = run("grade-classification.mjs", [join(HERE, "example-answers.json")]);
  assert.equal(r.status, 0);
  assert.match(r.stdout, /SCORE 8\/10 \(pass mark 8\) PASS/);
  assert.equal(run("grade-classification.mjs", [join(HERE, "example-answers.json"), "--pass", "9"]).status, 1);
});
